/**
 * Snippet Name: DS PPT R2 Storage (Post-Process)
 * Run: Everywhere
 * Description: After a presentation export finishes (currently /ds/v1/build-pptx,
 * generated by "12b ds ppt builder" — and any future PPT export route with the
 * same response shape, e.g. build-pptx-v2), uploads the finished .pptx to
 * Cloudflare R2, deletes the local copy immediately, and rewrites the response
 * URL to the stable retention-aware proxy URL.
 *
 * This is intentionally a REST response filter, NOT an edit to "12b ds ppt
 * builder" (which streams the .pptx to a local file via ZipArchive across ~500
 * lines of slide-rendering code, and was modified within the last day — i.e.
 * it is under active development right now). Post-processing the finished file
 * here means zero changes to that file, so there is no risk of this work
 * colliding with or reverting whatever is currently being iterated on there.
 *
 * Fail-open: if R2 isn't configured yet, or the upload fails for any reason,
 * the original local-download response passes through completely unchanged —
 * presentation export can never break because of this snippet. Once the
 * fetch/download flow in the PPT Studio UI is stable, the same
 * ds_hub_render_expiry_widget()-style UI used for images can be wired in to
 * show the file_id / expires_at / retention_notice this filter now adds to
 * the response — the file itself is already retention-tracked either way.
 *
 * Requires: "DS Storage & API Settings (R2 + Retention)" to be active.
 */

if ( ! defined('ABSPATH') ) exit;

add_filter('rest_request_after_callbacks', function( $response, $handlers, $request ) {
	if ( is_wp_error( $response ) || ! is_a( $response, 'WP_REST_Response' ) ) {
		return $response;
	}

	// Cheap fast-exit before any string work: only our own namespace, only POST
	// (every PPT export route is a POST), and only once R2 storage is active.
	$route = $request->get_route();
	if ( strpos( $route, '/ds/v1/' ) !== 0 ) return $response;
	if ( $request->get_method() !== 'POST' ) return $response;
	if ( ! function_exists( 'ds_hub_upload_generated_bytes' ) ) return $response;

	$data = $response->get_data();
	if ( ! is_array( $data ) || empty( $data['success'] ) || empty( $data['url'] ) || ! is_string( $data['url'] ) ) {
		return $response;
	}

	// Only ever touch our own local PPT export files — matching on the exact
	// local directory keeps this filter inert for every other REST response
	// on the site, regardless of which route produced this particular one.
	$upload      = wp_upload_dir();
	$local_base  = trailingslashit( $upload['baseurl'] ) . 'ds-ppt-downloads/';
	if ( strpos( $data['url'], $local_base ) !== 0 ) {
		return $response;
	}

	$fname = basename( parse_url( $data['url'], PHP_URL_PATH ) );
	$fpath = trailingslashit( $upload['basedir'] ) . 'ds-ppt-downloads/' . $fname;
	if ( ! file_exists( $fpath ) ) {
		return $response;
	}

	$bytes = file_get_contents( $fpath );
	if ( empty( $bytes ) ) {
		return $response;
	}

	$uid = get_current_user_id();
	$up  = ds_hub_upload_generated_bytes( $bytes, array(
		'file_type' => 'presentation',
		'source'    => 'generated',
		'extension' => 'pptx',
		'mime_type' => 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
		'user_id'   => $uid,
		'meta'      => array( 'filename' => isset( $data['filename'] ) ? $data['filename'] : $fname ),
	) );

	if ( is_wp_error( $up ) || empty( $up['url'] ) ) {
		// Upload failed (or R2 not configured) — keep the local file exactly as
		// it is and pass the original response through untouched. Log why, but
		// never break the export the user is waiting on.
		if ( function_exists( 'ds_hub_log' ) ) {
			ds_hub_log( 'ppt_upload_fallback_local', is_wp_error( $up ) ? $up->get_error_message() : 'unknown error' );
		}
		return $response;
	}

	// R2 upload succeeded — delete the local copy immediately (satisfies
	// "delete local copy immediately" the same way the image pipeline does)
	// and point the response at the stable retention-aware proxy URL.
	@unlink( $fpath );

	$file = function_exists( 'ds_hub_get_generated_file' ) ? ds_hub_get_generated_file( $up['id'] ) : null;
	$data['url']     = $up['url'];
	$data['file_id'] = (int) $up['id'];
	if ( $file && $file->expires_at ) {
		$data['expires_at']       = $file->expires_at;
		$data['retention_notice'] = function_exists( 'ds_hub_format_expiry_notice' ) ? ds_hub_format_expiry_notice( $file->expires_at ) : '';
	}
	$response->set_data( $data );
	return $response;

}, 10, 3 );
